const propertyId = "YOUR_PROPERTY_ID";
if (!/^\d+$/.test(propertyId)) throw Error("Configure a Google Analytics property ID");
const day = new Date().toISOString().slice(0, 10),
  d = (n) => new Date(Date.parse(day + "T00:00:00Z") + n * 86400000).toISOString().slice(0, 10);
return [
  {
    json: {
      propertyId,
      day,
      recentStart: d(-7),
      recentEnd: d(-1),
      previousStart: d(-14),
      previousEnd: d(-8),
    },
  },
];

function format({ state, recipient }) {
  if (typeof recipient !== "string" || !recipient.includes("@") || recipient.includes("YOUR_"))
    throw Error("Configure a report recipient");
  if (!state || state.index !== 6 || !Array.isArray(state.tables) || state.tables.length !== 6)
    throw Error("Incomplete report");
  const labels = [
      ["Page", "Page views", "Active users", "Views per user", "Event count"],
      [
        "Landing page",
        "Active users",
        "Engaged sessions",
        "Engagement rate",
        "Event count",
        "Average position",
        "Click-through rate",
        "Clicks",
        "Impressions",
      ],
      [
        "Country",
        "Active users",
        "New users",
        "Engagement rate",
        "Engaged sessions",
        "Event count",
        "Total users",
        "Sessions",
      ],
    ],
    sections = ["Page engagement", "Google Search", "Country views"],
    escape = (v) =>
      String(v).replace(
        /[&<>"']/g,
        (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
      );
  let html = "<h1>Google Analytics report</h1>";
  for (let i = 0; i < 6; i++) {
    if (!Array.isArray(state.tables[i])) throw Error("Invalid report table");
    html +=
      "<h2>" +
      sections[Math.floor(i / 2)] +
      " - " +
      (i % 2 ? "previous seven days" : "latest seven days") +
      "</h2>";
    const rows = state.tables[i];
    if (!rows.length) {
      html += "<p>No data.</p>";
      continue;
    }
    html +=
      "<table><thead><tr>" +
      labels[Math.floor(i / 2)].map((x) => "<th>" + escape(x) + "</th>").join("") +
      "</tr></thead><tbody>";
    for (const r of rows) {
      if (!Array.isArray(r) || r.length !== labels[Math.floor(i / 2)].length)
        throw Error("Invalid formatted row");
      html += "<tr>" + r.map((x) => "<td>" + escape(x) + "</td>").join("") + "</tr>";
    }
    html += "</tbody></table>";
  }
  return {
    to: recipient,
    subject: "Google Analytics report before " + state.day + " UTC",
    body: html,
  };
}

const names = [
    "Get Page Engagement Stats for this week",
    "Get Page Engagement Stats for prior week",
    "Get Google Search Results for this week",
    "Get Google Search Results for prior week",
    "Get Country views data for this week",
    "Get Country views data for prior week",
  ],
  lengths = [4, 4, 8, 8, 7, 7],
  tables = [];
for (let i = 0; i < names.length; i++) {
  const pages = $(names[i]).all(),
    rows = [];
  let count = null;
  for (const p of pages) {
    const r = p.json?.body;
    if (!r || typeof r !== "object" || !Array.isArray(r.rows ?? []))
      throw Error("Invalid analytics response");
    const c = r.rowCount ?? 0;
    if (!Number.isSafeInteger(c) || c < 0 || (count !== null && count !== c))
      throw Error("Analytics row count changed");
    count = c;
    rows.push(...(r.rows ?? []));
  }
  if (count === null || count !== rows.length) throw Error("Incomplete analytics response");
  tables.push(
    rows.map((x) => {
      if (
        !Array.isArray(x.dimensionValues) ||
        x.dimensionValues.length !== 1 ||
        typeof x.dimensionValues[0]?.value !== "string" ||
        !Array.isArray(x.metricValues) ||
        x.metricValues.length !== lengths[i] ||
        x.metricValues.some((v) => typeof v?.value !== "string")
      )
        throw Error("Invalid analytics row");
      return [x.dimensionValues[0].value, ...x.metricValues.map((v) => v.value)];
    }),
  );
}
const state = { index: 6, day: $("Prepare report dates").first().json.day, tables };
return [{ json: format({ state, recipient: "YOUR_REPORT_EMAIL" }) }];
